CREATE DATABASE IF NOT EXISTS manas_mitra CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE manas_mitra;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('patient','caregiver','doctor','admin') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NULL UNIQUE, name VARCHAR(100) NOT NULL, preferred_name VARCHAR(100), age TINYINT UNSIGNED, preferred_language VARCHAR(10) DEFAULT 'en', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS caregivers (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NULL, patient_id BIGINT UNSIGNED NOT NULL, display_name VARCHAR(100) NOT NULL, phone VARCHAR(30), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL, title VARCHAR(90) NOT NULL, time TIME NOT NULL, icon VARCHAR(10) DEFAULT '◯', status ENUM('pending','done','snoozed','missed') DEFAULT 'pending', repeat_frequency ENUM('Daily','Weekly','Once') DEFAULT 'Daily', priority ENUM('Normal','High') DEFAULT 'Normal', active BOOLEAN DEFAULT TRUE, completed_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (patient_id,time), FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reminders (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL, title VARCHAR(90) NOT NULL, time TIME NOT NULL, kind VARCHAR(10), repeat_frequency ENUM('Daily','Weekly','Once') DEFAULT 'Daily', priority ENUM('Normal','High') DEFAULT 'Normal', active BOOLEAN DEFAULT TRUE, snoozed_until DATETIME NULL, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS memories (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL, title VARCHAR(100) NOT NULL, description TEXT NOT NULL, category VARCHAR(35) NOT NULL, memory_date VARCHAR(50), icon VARCHAR(10), consented_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversations (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversation_messages (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, conversation_id BIGINT UNSIGNED NOT NULL, role ENUM('user','assistant') NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cognitive_games (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, slug VARCHAR(40) UNIQUE NOT NULL, title VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS game_results (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL, game_id INT UNSIGNED NOT NULL, correct BOOLEAN NOT NULL, response_ms INT UNSIGNED, difficulty VARCHAR(25), played_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE, FOREIGN KEY (game_id) REFERENCES cognitive_games(id));
CREATE TABLE IF NOT EXISTS emergency_contacts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL, relation VARCHAR(50), priority TINYINT UNSIGNED DEFAULT 1, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL, title VARCHAR(120) NOT NULL, body VARCHAR(500), read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS user_settings (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL UNIQUE, language VARCHAR(10) DEFAULT 'en', theme VARCHAR(12) DEFAULT 'system', font_size VARCHAR(10) DEFAULT 'medium', high_contrast BOOLEAN DEFAULT FALSE, reduced_motion BOOLEAN DEFAULT FALSE, auto_speak BOOLEAN DEFAULT FALSE, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS patient_preferences (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT UNSIGNED NOT NULL, preference_key VARCHAR(100) NOT NULL, preference_value VARCHAR(500) NOT NULL, UNIQUE KEY (patient_id,preference_key), FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE);
