-- Active v2 aggregate store (created automatically by storageService).
CREATE TABLE IF NOT EXISTS app_documents (document_key VARCHAR(150) PRIMARY KEY, document_json JSON NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
